LPot := m2 Phibar[ii] Phi[ii] + mu2 Chibar Chi + lam1 (Phibar[ii] Phi[ii])^2 + lam2 (Chibar Chi)^2 + lam3 Phibar[ii] Phi[ii] Chibar Chi;

