LNuYuk := -ynu[ff1, ff2] LLbar[sp, ii, ff1].NR[sp, ff2] Phibar[jj] Eps[ii, jj] - yM[ff1, ff2] NRbar[sp, ff1].CC[NR[sp, ff2]] Chi;

